model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  r: Number
}

component BallSimulation {
  state balls: Ball[] = []
  state paused = false
  state frames = 0
  ref canvas
  ref animationId

  fn initBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        r: 10
      })
    }
    frames = 0
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 4,
      vy: (Math.random() - 0.5) * 4,
      r: 10
    })
  }

  fn togglePause {
    paused = !paused
  }

  fn reset {
    paused = false
    initBalls()
  }

  fn updatePhysics {
    for let b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy

      if b.x - b.r < 0 {
        b.x = b.r
        b.vx = -b.vx
      }
      if b.x + b.r > 400 {
        b.x = 400 - b.r
        b.vx = -b.vx
      }
      if b.y - b.r < 0 {
        b.y = b.r
        b.vy = -b.vy
      }
      if b.y + b.r > 300 {
        b.y = 300 - b.r
        b.vy = -b.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let b1 = balls[i]
        let b2 = balls[j]
        let dx = b2.x - b1.x
        let dy = b2.y - b1.y
        let dist = Math.sqrt(dx * dx + dy * dy)

        if dist < b1.r + b2.r {
          let temp = b1.vx
          b1.vx = b2.vx
          b2.vx = temp

          temp = b1.vy
          b1.vy = b2.vy
          b2.vy = temp

          if dist > 0) {
            let overlap = b1.r + b2.r - dist
            let nx = dx / dist
            let ny = dy / dist
            b1.x -= nx * overlap * 0.5
            b1.y -= ny * overlap * 0.5
            b2.x += nx * overlap * 0.5
            b2.y += ny * overlap * 0.5
          }
        }
      }
    }
  }

  fn draw {
    let ctx = canvas.getContext("2d")
    ctx.fillStyle = "#fff"
    ctx.fillRect(0, 0, 400, 300)
    ctx.strokeStyle = "#000"
    ctx.lineWidth = 1
    ctx.strokeRect(0, 0, 400, 300)

    ctx.fillStyle = "#e11d48"
    for let b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn animate {
    if !paused {
      updatePhysics()
      frames++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    initBalls()
    draw()
    animationId = requestAnimationFrame(animate)
    cleanup {
      cancelAnimationFrame(animationId)
    }
  }

  column gap=4 {
    canvas id="sim" ref=canvas width=400 height=300 style="border: 1px solid #ccc"
    row gap=4 {
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Agregar" -> addBall()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
  }
}

