import React, { useRef, useEffect, useState } from 'react';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [balls, setBalls] = useState<Ball[]>([]);
  const [paused, setPaused] = useState(false);
  const [frameCount, setFrameCount] = useState(0);
  const animationRef = useRef<number | null>(null);
  const ballsRef = useRef<Ball[]>([]);
  const frameCountRef = useRef(0);
  const pausedRef = useRef(false);

  const CANVAS_WIDTH = 400;
  const CANVAS_HEIGHT = 300;
  const BALL_RADIUS = 10;
  const GRAVITY = 0.2;

  const createBall = (): Ball => ({
    x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
    y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
    vx: (Math.random() - 0.5) * 8,
    vy: (Math.random() - 0.5) * 8,
    radius: BALL_RADIUS,
    color: `hsl(${Math.random() * 360}, 100%, 50%)`,
  });

  const initializeBalls = (count: number) => {
    const newBalls = Array.from({ length: count }, () => createBall());
    ballsRef.current = newBalls;
    setBalls(newBalls);
    frameCountRef.current = 0;
    setFrameCount(0);
  };

  useEffect(() => {
    initializeBalls(5);
  }, []);

  const checkCollision = (ball1: Ball, ball2: Ball): boolean => {
    const dx = ball2.x - ball1.x;
    const dy = ball2.y - ball1.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < ball1.radius + ball2.radius;
  };

  const resolveCollision = (ball1: Ball, ball2: Ball) => {
    const temp1vx = ball1.vx;
    const temp1vy = ball1.vy;
    ball1.vx = ball2.vx;
    ball1.vy = ball2.vy;
    ball2.vx = temp1vx;
    ball2.vy = temp1vy;
  };

  const updateBalls = () => {
    const ballsCopy = ballsRef.current;

    // Apply gravity
    ballsCopy.forEach((ball) => {
      ball.vy += GRAVITY;
    });

    // Update positions
    ballsCopy.forEach((ball) => {
      ball.x += ball.vx;
      ball.y += ball.vy;

      // Bounce off walls
      if (ball.x - ball.radius < 0) {
        ball.x = ball.radius;
        ball.vx = Math.abs(ball.vx);
      }
      if (ball.x + ball.radius > CANVAS_WIDTH) {
        ball.x = CANVAS_WIDTH - ball.radius;
        ball.vx = -Math.abs(ball.vx);
      }
      if (ball.y - ball.radius < 0) {
        ball.y = ball.radius;
        ball.vy = Math.abs(ball.vy);
      }
      if (ball.y + ball.radius > CANVAS_HEIGHT) {
        ball.y = CANVAS_HEIGHT - ball.radius;
        ball.vy = -Math.abs(ball.vy);
      }
    });

    // Check collisions
    for (let i = 0; i < ballsCopy.length; i++) {
      for (let j = i + 1; j < ballsCopy.length; j++) {
        if (checkCollision(ballsCopy[i], ballsCopy[j])) {
          resolveCollision(ballsCopy[i], ballsCopy[j]);
        }
      }
    }
  };

  const drawBalls = (ctx: CanvasRenderingContext2D) => {
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ballsRef.current.forEach((ball) => {
      ctx.fillStyle = ball.color;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(0, 0, 0, 0.3)';
      ctx.lineWidth = 1;
      ctx.stroke();
    });
  };

  const animate = () => {
    if (!pausedRef.current) {
      updateBalls();
      frameCountRef.current += 1;
      setFrameCount(frameCountRef.current);
    }

    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      if (ctx) {
        drawBalls(ctx);
      }
    }

    animationRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    animationRef.current = requestAnimationFrame(animate);
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const handleAddBall = () => {
    const newBall = createBall();
    ballsRef.current.push(newBall);
    setBalls([...ballsRef.current]);
  };

  const handleTogglePause = () => {
    pausedRef.current = !pausedRef.current;
    setPaused(!paused);
  };

  const handleRestart = () => {
    pausedRef.current = false;
    setPaused(false);
    initializeBalls(5);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100 p-4">
      <div className="bg-white rounded-lg shadow-lg p-8">
        <h1 className="text-3xl font-bold mb-6 text-center text-gray-800">
          Simulador de Pelotas
        </h1>

        <canvas
          ref={canvasRef}
          id="sim"
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          className="border-4 border-gray-800 mb-6 bg-white"
        />

        <div className="mb-6 flex justify-between text-lg font-semibold text-gray-700">
          <span>Pelotas: {ballsRef.current.length}</span>
          <span>Cuadros: {frameCount}</span>
        </div>

        <div className="flex gap-4 justify-center flex-wrap">
          <button
            onClick={handleAddBall}
            className="px-6 py-2 bg-green-500 hover:bg-green-600 text-white font-bold rounded-lg transition"
          >
            Agregar
          </button>
          <button
            onClick={handleTogglePause}
            className="px-6 py-2 bg-yellow-500 hover:bg-yellow-600 text-white font-bold rounded-lg transition"
          >
            {paused ? 'Reanudar' : 'Pausar'}
          </button>
          <button
            onClick={handleRestart}
            className="px-6 py-2 bg-red-500 hover:bg-red-600 text-white font-bold rounded-lg transition"
          >
            Reiniciar
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useRef, useEffect, useState } from 'react';

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [ballCount, setBallCount] = useState(5);
  const [frameCount, setFrameCount] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const ballsRef = useRef<Ball[]>([]);
  const animationIdRef = useRef<number | null>(null);
  const frameCountRef = useRef(0);

  const CANVAS_WIDTH = 400;
  const CANVAS_HEIGHT = 300;
  const BALL_RADIUS = 10;
  const GRAVITY = 0.2;

  const getRandomColor = () => {
    const colors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2'];
    return colors[Math.floor(Math.random() * colors.length)];
  };

  const createBall = (): Ball => {
    return {
      x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
      y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      radius: BALL_RADIUS,
      color: getRandomColor(),
    };
  };

  const initializeBalls = (count: number) => {
    ballsRef.current = Array.from({ length: count }, () => createBall());
    setBallCount(count);
    frameCountRef.current = 0;
    setFrameCount(0);
  };

  useEffect(() => {
    initializeBalls(5);
  }, []);

  const addBall = () => {
    if (!isPaused) {
      ballsRef.current.push(createBall());
      setBallCount(ballsRef.current.length);
    }
  };

  const handlePauseResume = () => {
    setIsPaused(!isPaused);
  };

  const handleReset = () => {
    setIsPaused(false);
    initializeBalls(5);
  };

  const drawBalls = (ctx: CanvasRenderingContext2D) => {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ballsRef.current.forEach((ball) => {
      ctx.fillStyle = ball.color;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#333333';
      ctx.lineWidth = 2;
      ctx.stroke();
