  const createRandomBall = (): Ball => ({
    x: Math.random() * (CANVAS_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
    y: Math.random() * (CANVAS_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
    vx: (Math.random() - 0.5) * 8,
    vy: (Math.random() - 0.5) * 8,
    radius: BALL_RADIUS,
  });

  const initializeBalls = () => {
    const initialBalls: Ball[] = [];
    for (let i = 0; i < 5; i++) {
      initialBalls.push(createRandomBall());
    }
    setBalls(initialBalls);
    setFrameCount(0);
  };

  const addBall = () => {
    setBalls([...balls(), createRandomBall()]);
  };

  const togglePause = () => {
    setIsRunning(!isRunning());
  };

  const reinitialize = () => {
    setIsRunning(true);
    initializeBalls();
  };

  const updatePhysics = () => {
    let currentBalls = [...balls()];

    // Apply gravity and update positions
    currentBalls = currentBalls.map(ball => ({
      ...ball,
      vy: ball.vy + GRAVITY,
      x: ball.x + ball.vx,
      y: ball.y + ball.vy,
    }));

    // Handle wall collisions
    currentBalls = currentBalls.map(ball => {
      let newBall = { ...ball };

      if (newBall.x - newBall.radius <= 0) {
        newBall.x = newBall.radius;
        newBall.vx = Math.abs(newBall.vx);
      }
      if (newBall.x + newBall.radius >= CANVAS_WIDTH) {
        newBall.x = CANVAS_WIDTH - newBall.radius;
        newBall.vx = -Math.abs(newBall.vx);
      }
      if (newBall.y - newBall.radius <= 0) {
        newBall.y = newBall.radius;
        newBall.vy = Math.abs(newBall.vy);
      }
      if (newBall.y + newBall.radius >= CANVAS_HEIGHT) {
        newBall.y = CANVAS_HEIGHT - newBall.radius;
        newBall.vy = -Math.abs(newBall.vy);
      }

      return newBall;
    });

    // Handle ball-to-ball collisions (elastic collision - exchange velocities)
    for (let i = 0; i < currentBalls.length; i++) {
      for (let j = i + 1; j < currentBalls.length; j++) {
        const ball1 = currentBalls[i];
        const ball2 = currentBalls[j];

        const dx = ball2.x - ball1.x;
        const dy = ball2.y - ball1.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < ball1.radius + ball2.radius && distance > 0) {
          // Exchange velocities
          const tempVx = ball1.vx;
          const tempVy = ball1.vy;
          currentBalls[i].vx = ball2.vx;
          currentBalls[i].vy = ball2.vy;
          currentBalls[j].vx = tempVx;
          currentBalls[j].vy = tempVy;

          // Separate balls to prevent overlap
          const overlap = (ball1.radius + ball2.radius - distance) / 2;
          const angle = Math.atan2(dy, dx);
          currentBalls[i].x -= overlap * Math.cos(angle);
          currentBalls[i].y -= overlap * Math.sin(angle);
          currentBalls[j].x += overlap * Math.cos(angle);
          currentBalls[j].y += overlap * Math.sin(angle);
        }
      }
    }

    setBalls(currentBalls);
  };

  const draw = () => {
    if (!canvasRef) return;

    const ctx = canvasRef.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.strokeRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    balls().forEach(ball => {
      ctx.fillStyle = '#00d4ff';
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fill();
    });
  };

  const animate = () => {
    if (isRunning()) {
      updatePhysics();
      setFrameCount(fc => fc + 1);
    }
    draw();
    animationId = requestAnimationFrame(animate);
  };

  createEffect(() => {
    if (!isInitialized && canvasRef) {
      isInitialized = true;
      initializeBalls();
      animate();

      onCleanup(() => {
        if (animationId !== null) {
          cancelAnimationFrame(animationId);
        }
      });
    }
  });

  return (
    <div class="flex flex-col items-center gap-6 p-8 bg-gray-800 rounded-lg shadow-lg">
      <h1 class="text-3xl font-bold text-white">Simulador de Pelotas</h1>

      <canvas
        ref={canvasRef}
        id="sim"
        width={CANVAS_WIDTH}
        height={CANVAS_HEIGHT}
        class="border-2 border-cyan-400 bg-gray-900 rounded"
      />

      <div class="flex gap-4">
        <button
          onClick={addBall}
          class="px-6 py-2 bg-green-600 hover:bg-green-700 text-white font-bold rounded transition"
        >
          Agregar
        </button>
        <button
          onClick={togglePause}
          class="px-6 py-2 bg-yellow-600 hover:bg-yellow-700 text-white font-bold rounded transition"
        >
          {isRunning() ? 'Pausar' : 'Reanudar'}
        </button>
        <button
          onClick={reinitialize}
          class="px-6 py-2 bg-red-600 hover:bg-red-700 text-white font-bold rounded transition"
        >
          Reiniciar
        </button>
      </div>

      <div class="text-white text-lg font-semibold">
        <p>Pelotas: {balls().length}</p>
        <p>Cuadros: {frameCount()}</p>
      </div>
    </div>
  );
}
